        const key = `${x + dx},${y + dy}`;
        neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
      }
    }
  }

  const next: Cell[] = [];
  for (const [key, count] of neighborCounts) {
    const survives = live.has(key) && (count === 2 || count === 3);
    const born = !live.has(key) && count === 3;
    if (survives || born) {
